#!/usr/bin/env python3
"""Direct-manipulation controller for structured Multiwrite cover pages."""
JS=r'''<script id="d2-cover-interaction">(()=>{const page='multiwrite-cover',canvas=document.querySelector('.canvas');if(!canvas)return;let sel=null,gesture=null;const box=document.createElement('div');box.id='d2-selection';box.hidden=true;for(const d of ['nw','n','ne','e','se','s','sw','w']){const h=document.createElement('i');h.className='d2-h '+d;h.dataset.handle=d;box.appendChild(h)}canvas.appendChild(box);function rect(){if(!sel){box.hidden=true;return}box.hidden=false;Object.assign(box.style,{left:sel.offsetLeft+'px',top:sel.offsetTop+'px',width:sel.offsetWidth+'px',height:sel.offsetHeight+'px'})}function pick(n){sel=n;rect();parent.postMessage({type:'dore-select',page_id:page,id:n.dataset.id,field:'text',value:n.innerText},'*');parent.postMessage({type:'dore-selection-set',page_id:page,ids:[n.dataset.id],primary:n.dataset.id},'*')}async function save(){if(!sel)return;const patch={x:sel.offsetLeft,y:sel.offsetTop,w:sel.offsetWidth,h:sel.offsetHeight};const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'set_node',page_id:page,id:sel.dataset.id,patch})});parent.postMessage({type:r.ok?'dore-saved':'dore-error',page_id:page,id:sel.dataset.id},'*')}box.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-handle]');if(!h||!sel)return;e.preventDefault();e.stopPropagation();gesture={kind:'resize',dir:h.dataset.handle,x:e.clientX,y:e.clientY,l:sel.offsetLeft,t:sel.offsetTop,w:sel.offsetWidth,h:sel.offsetHeight};box.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerdown',e=>{if(e.target.closest('#d2-selection'))return;const n=e.target.closest('[data-id]');if(!n)return;e.preventDefault();pick(n);gesture={kind:'move',x:e.clientX,y:e.clientY,l:n.offsetLeft,t:n.offsetTop};canvas.setPointerCapture(e.pointerId)});function resize(e){const g=gesture,dx=e.clientX-g.x,dy=e.clientY-g.y,min=12;let l=g.l,t=g.t,w=g.w,h=g.h;if(g.dir.includes('e'))w=Math.max(min,g.w+dx);if(g.dir.includes('s'))h=Math.max(min,g.h+dy);if(g.dir.includes('w')){w=Math.max(min,g.w-dx);l=g.l+(g.w-w)}if(g.dir.includes('n')){h=Math.max(min,g.h-dy);t=g.t+(g.h-h)}if(e.shiftKey&&g.w>0&&g.h>0&&/[nsew]{2}/.test(g.dir)){const ratio=g.w/g.h;if(w/h>ratio)w=h*ratio;else h=w/ratio;if(g.dir.includes('w'))l=g.l+(g.w-w);if(g.dir.includes('n'))t=g.t+(g.h-h)}Object.assign(sel.style,{left:Math.round(l)+'px',top:Math.round(t)+'px',width:Math.round(w)+'px',height:Math.round(h)+'px'});rect()}function move(e){sel.style.left=Math.round(gesture.l+e.clientX-gesture.x)+'px';sel.style.top=Math.round(gesture.t+e.clientY-gesture.y)+'px';rect()}function pointerMove(e){if(!gesture||!sel)return;gesture.kind==='resize'?resize(e):move(e)}canvas.addEventListener('pointermove',pointerMove);box.addEventListener('pointermove',pointerMove);async function end(){if(!gesture)return;gesture=null;await save()}canvas.addEventListener('pointerup',end);box.addEventListener('pointerup',end);addEventListener('keydown',e=>{if(!sel||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;let s=e.shiftKey?10:1,dx=0,dy=0;if(e.key==='ArrowLeft')dx=-s;if(e.key==='ArrowRight')dx=s;if(e.key==='ArrowUp')dy=-s;if(e.key==='ArrowDown')dy=s;if(!dx&&!dy)return;e.preventDefault();sel.style.left=sel.offsetLeft+dx+'px';sel.style.top=sel.offsetTop+dy+'px';rect();save()})})()</script>'''
CSS='''<style>#d2-selection{position:absolute;z-index:9998;border:1px solid #b49a55;pointer-events:auto}#d2-selection[hidden]{display:none}.d2-h{position:absolute;width:8px;height:8px;background:#fbfaf6;border:1px solid #8c6818;border-radius:1px}.d2-h.nw{left:-5px;top:-5px;cursor:nwse-resize}.d2-h.n{left:50%;top:-5px;transform:translateX(-50%);cursor:ns-resize}.d2-h.ne{right:-5px;top:-5px;cursor:nesw-resize}.d2-h.e{right:-5px;top:50%;transform:translateY(-50%);cursor:ew-resize}.d2-h.se{right:-5px;bottom:-5px;cursor:nwse-resize}.d2-h.s{left:50%;bottom:-5px;transform:translateX(-50%);cursor:ns-resize}.d2-h.sw{left:-5px;bottom:-5px;cursor:nesw-resize}.d2-h.w{left:-5px;top:50%;transform:translateY(-50%);cursor:ew-resize}</style>'''
def augment(html):return html.replace('</head>',CSS+'</head>',1).replace('</body>',JS+'</body>',1)
